<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { getJSON } from '../api'
import { STATUS_TYPE, STATUS_LABEL, TERMINAL, fmtTime } from '../status'
const rows=ref([]),status=ref(''),query=ref(''),loading=ref(false),error=ref('')
let timer,busy=false
const filtered=computed(()=>rows.value.filter(r=>(!status.value||r.status===status.value)&&(!query.value||r.task_no.toLowerCase().includes(query.value.toLowerCase())||r.robot_id.includes(query.value))))
const active=computed(()=>rows.value.filter(r=>!TERMINAL.includes(r.status)).length)
const attention=computed(()=>rows.value.filter(r=>['BLOCKED','TIMEOUT','FAILED'].includes(r.status)).length)
async function load(){if(busy)return;busy=true;loading.value=true;try{rows.value=await getJSON('/api/tasks?limit=200');error.value=''}catch(e){error.value=e.message}finally{busy=false;loading.value=false}}
onMounted(()=>{load();timer=setInterval(load,5000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>
<template>
 <div class="page-heading"><div><div class="eyebrow">MISSION MANAGEMENT</div><h1>巡检任务</h1><p>从下发到完成，追踪每一次巡检的执行过程。</p></div><router-link to="/chat"><el-button type="primary">＋ 让助手安排巡检</el-button></router-link></div>
 <div class="task-summary"><div><span>任务记录</span><strong>{{ rows.length }}</strong><small>最近 200 条</small></div><div><span>进行中</span><strong>{{ active }}</strong><small>等待或执行中的任务</small></div><div><span>已完成</span><strong>{{ rows.filter(r=>r.status==='DONE').length }}</strong><small>巡检流程已结束</small></div><div><span>需要关注</span><strong class="amber">{{ attention }}</strong><small>阻塞 / 超时 / 失败</small></div></div>
 <div class="surface"><div class="task-toolbar"><div class="filter-tabs"><button :class="{on:!status}" @click="status=''">全部任务</button><button :class="{on:status==='NAVIGATING'}" @click="status='NAVIGATING'">导航中</button><button :class="{on:status==='BLOCKED'}" @click="status='BLOCKED'">待处理</button><button :class="{on:status==='DONE'}" @click="status='DONE'">已完成</button></div><div class="tools"><el-input v-model="query" placeholder="搜索任务号 / 机器人" clearable style="width:190px"/><el-select v-model="status" clearable placeholder="全部状态" style="width:125px"><el-option v-for="(label,s) in STATUS_LABEL" :key="s" :label="label" :value="s"/></el-select><el-button :loading="loading" @click="load" aria-label="刷新任务">↻</el-button></div></div>
 <el-alert v-if="error" :title="'任务加载失败：'+error" type="warning" :closable="false"/>
 <el-table :data="filtered" @row-click="r=>$router.push('/tasks/'+r.task_no)" class="task-table"><el-table-column label="任务" min-width="200"><template #default="{row}"><router-link :to="'/tasks/'+row.task_no" class="task-id">{{ row.task_no }}</router-link><small class="task-sub">{{ row.source==='chat'?'智能助手创建':row.source==='manual'?'手动创建':'计划任务' }}</small></template></el-table-column><el-table-column label="执行状态" width="135"><template #default="{row}"><el-tag :type="STATUS_TYPE[row.status]">● {{ STATUS_LABEL[row.status] || row.status }}</el-tag></template></el-table-column><el-table-column label="机器人" width="115"><template #default="{row}"><span class="device-label">◈ {{ row.robot_id }}</span></template></el-table-column><el-table-column label="优先级" width="95"><template #default="{row}"><span class="priority">P{{ row.priority }}</span></template></el-table-column><el-table-column label="创建时间" min-width="180"><template #default="{row}">{{ fmtTime(row.created_at) }}</template></el-table-column><el-table-column label="完成时间" min-width="180"><template #default="{row}">{{ fmtTime(row.finished_at) }}</template></el-table-column><el-table-column width="65"><template #default="{row}"><router-link :to="'/tasks/'+row.task_no" :aria-label="'查看任务 '+row.task_no">↗</router-link></template></el-table-column><template #empty><div class="empty-state">{{ error?'暂时无法获取任务':query||status?'没有符合条件的任务':'暂无任务，向助手描述你的巡检需求即可开始。' }}</div></template></el-table>
 <div class="table-footer"><span>{{ filtered.length }} 条匹配记录</span><span>每 5 秒自动更新</span></div></div>
</template>
<style scoped>
.task-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:24px}.task-summary>div{background:white;border:1px solid var(--line);padding:20px 22px;border-radius:9px}.task-summary span{font-size:11px;color:#81907d;display:block}.task-summary strong{font-size:31px;display:block;color:#31523c;font-weight:550;padding:12px 0}.task-summary small{font-size:10px;color:#9ca78f}.task-summary .amber{color:#ae8a49}.task-toolbar{padding:17px 20px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.filter-tabs{display:flex;gap:5px}.filter-tabs button{background:none;border:0;padding:8px 12px;border-radius:5px;font-size:11px;color:#89987e}.filter-tabs button.on{background:#edf3e7;color:#48733c;font-weight:600}.tools{display:flex;gap:9px}.task-table{cursor:pointer}.task-id{font-size:12px;color:#365b3e;font-weight:550}.task-sub{display:block;color:#9ba88c;font-size:9px;margin-top:5px}.device-label{font-size:11px;color:#748a63}.priority{background:#f1f4eb;color:#82936e;font-size:10px;padding:4px 7px;border-radius:4px}.table-footer{padding:15px 20px;display:flex;justify-content:space-between;font-size:10px;color:#9aa58e}@media(max-width:800px){.task-summary{grid-template-columns:repeat(2,1fr);gap:10px}.tools{flex-wrap:wrap}.task-toolbar{padding:12px}.filter-tabs button{padding:8px}}
</style>